mapper.select:
${pagingTop} SELECT homepage_id, club_idx, club_name, club_date, club_members, leader_name, user_phone, user_email, postcode, address_base, address_detailed, book_area, book_quantity, relay_plan, approval_status, delete_yn, add_id, add_date FROM BOOK_RELAY_CLUB WHERE homepage_id = #{homepage_id} AND delete_yn = 'N'
AND ${search_type} LIKE '%'||#{search_text}||'%'
ORDER BY club_idx DESC ${pagingBottom}

mapper.update:
UPDATE 
	BOOK_RELAY_CLUB
SET
	delete_yn = 'Y',
	delete_id = #{delete_id}
WHERE
	homepage_id = #{homepage_id}
AND club_idx = #{club_idx}

UPDATE 
	BOOK_RELAY_CLUB
SET
	approval_status = #{approval_status}
WHERE
	homepage_id = #{homepage_id}
AND club_idx = #{club_idx}
